contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 depositAmount, address recipient) public payable {
        require(address(this).balance >= depositAmount);

        // Setup: make the test contract the creator and give c a nonzero balance.
        c.deposit{value: depositAmount}();

        uint256 beforeBalance = address(c).balance;

        bool reverted;
        try c.migrateTo(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = address(c).balance;
        uint256 recipientBalance = recipient.balance;
        uint256 testBalance = address(this).balance;

        // General rule: migrateTo succeeds iff msg.sender is the creator; on success
        // c's full balance moves to recipient; on failure c's balance is unchanged.
        assert(
            (reverted == (recipient != recipient)) &&
            (!reverted ? (afterBalance == 0 && recipientBalance == beforeBalance + beforeBalance - beforeBalance) : (afterBalance == beforeBalance && recipientBalance == testBalance))
        );
    }

    receive() external payable {}
}

